arguments.command:
cd /app; python3 -c "
import pandas as pd
df=pd.read_csv('dataset/hospital_compensation_registry.csv')
d=dict(zip(df.patient_id,df.emergency_contact_patient_id)); nm=dict(zip(df.patient_id,df.full_name)); rd=dict(zip(df.patient_id,df.record_date)); rs=dict(zip(df.patient_id,df.compensation_reason))
inv={}
for a,b in d.items(): inv.setdefault(b,[]).append(a)
def s(p): return f'{p} {nm[p]} [{rd[p]} {rs[p]}]'
for p in ['PAT_006','PAT_033','PAT_265']:
  print('#####',s(p))
  print(' out:',s(d[p]),' -> out2:',s(d[d[p]]))
  for q in inv.get(d[p],[]): print('   co-listers of contact:',s(q))
  for q in inv.get(p,[]):
    print(' in:',s(q))
    for r in inv.get(q,[]): print('    in2:',s(r))
for p in df[(df.second_name=='Jones')&df.record_date.isna()].patient_id:
  print(s(p),'-> ',s(d[p]),' listed by',[s(q) for q in inv.get(p,[])])
"

